-- ----------------------------
-- Table structure for big_screen
-- ----------------------------
DROP TABLE IF EXISTS `big_screen`;
CREATE TABLE `big_screen`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `screen_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `user_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
  `group_id` bigint NULL DEFAULT NULL,
  `config` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `screen_id`(`screen_id` ASC) USING BTREE,
  INDEX `group_id`(`group_id` ASC) USING BTREE,
  INDEX `idx_big_screen_screen_id`(`screen_id` ASC) USING BTREE,
  INDEX `idx_big_screen_user_id`(`user_id` ASC) USING BTREE,
  CONSTRAINT `big_screen_ibfk_1` FOREIGN KEY (`group_id`) REFERENCES `screen_groups` (`id`) ON DELETE SET NULL ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = Dynamic;

